UPDATE public.weekly_report SET payload = jsonb_set(payload, '{sowhat,lede}', to_jsonb('Luxury signings are running about 20 contracts a week, well ahead of the 52-week average, and the pace is still picking up. Q3 is historically the slowest quarter of the year, so read this quarter''s pace against that seasonal backdrop, not as a standalone signal.'::text)) WHERE week_start = '2026-07-13';